_FONT_TABLES: Dict[str, Mapping[str, int]] = {
    "Helvetica": _HELVETICA_WIDTHS,
    "Helvetica-Bold": _HELVETICA_BOLD_WIDTHS,
    "Times-Roman": _TIMES_ROMAN_WIDTHS,
    # Measured tables for the vendored delivery fonts.
    "Public Sans": _PUBLIC_SANS_WIDTHS,
    "Public Sans SemiBold": _PUBLIC_SANS_SEMIBOLD_WIDTHS,
    "Fraunces": _FRAUNCES_WIDTHS,
    "Fraunces Italic": _FRAUNCES_ITALIC_WIDTHS,
    "IBM Plex Mono": _PLEX_MONO_WIDTHS,
}

#: Width (per 1000 units) assumed for characters missing from a table.
#: Deliberately on the wide side so unknown glyphs over- rather than
#: under-predict line breaks.
_DEFAULT_CHAR_WIDTH = 600


def string_width(text: str, font_name: str, font_size: float) -> float:
    """Estimated advance width of *text* in points.

    Mirrors ReportLab's ``stringWidth`` for the standard Helvetica /
    Helvetica-Bold / Times-Roman metrics. Unknown font names fall back to
    Helvetica; unknown characters use a conservative default width.
    """
    table = _FONT_TABLES.get(font_name, _HELVETICA_WIDTHS)
    total = 0
    for ch in text:
        total += table.get(ch, _DEFAULT_CHAR_WIDTH)
    return total * font_size / 1000.0
